  <!-- IN-SIDEBAR PERSISTENT PROFILE FORM (collapsed by default, shown on Add/Edit) -->
  <div class="section form-section-noborder hidden" id="profile-form-section" style="display: none;">
    <div class="section-title-row">
      <span class="section-title" id="form-title">CREATE / EDIT PROFILE</span>
      <button type="button" class="icon-btn-ghost" title="Close" data-action="cancelProfileForm">&times;</button>
    </div>
    <div class="form-box">
      <div id="form-error-msg" class="banner-error hidden"></div>
      <input type="hidden" id="form-profile-id" value="" />
      
      <div class="form-group">
        <label class="form-label" for="form-name">Profile Name <span class="req">*</span></label>
        <input type="text" id="form-name" class="input-text" placeholder="e.g. work, personal, opensource" autocomplete="off" />
      </div>

      <div class="form-group">
        <label class="form-label" for="form-git-name">Git Author Name <span class="req">*</span></label>
        <input type="text" id="form-git-name" class="input-text" placeholder="e.g. Work User" autocomplete="off" />
      </div>

      <div class="form-group">
        <label class="form-label" for="form-git-email">Git Email <span class="req">*</span></label>
        <input type="email" id="form-git-email" class="input-text" placeholder="e.g. work@company.com" autocomplete="off" />
      </div>

      <div class="form-group">
        <label class="form-label" for="form-gh-user">GitHub Username <span class="opt">(optional)</span></label>
        <input type="text" id="form-gh-user" class="input-text" placeholder="e.g. work-user" autocomplete="off" />
      </div>

      <div class="form-group">
        <label class="form-label" for="form-host">GitHub Host</label>
        <input type="text" id="form-host" class="input-text" value="github.com" placeholder="github.com" autocomplete="off" />
      </div>

      <div class="form-group">
        <label class="form-label" for="form-auth-type">Authentication Type</label>
        <select id="form-auth-type" class="input-text">
          <option value="none">None</option>
          <option value="pat" selected>Personal Access Token (PAT)</option>
          <option value="ssh">SSH Key</option>
        </select>
      </div>

      <div class="form-group" id="form-group-pat">
        <label class="form-label" for="form-pat">Personal Access Token (PAT) <span class="opt">(optional)</span></label>
        <div class="pat-row">
          <input type="password" id="form-pat" class="input-text" placeholder="ghp_xxxxxxxxxxxx" autocomplete="off" />
          <button type="button" id="btn-toggle-pat" class="btn btn-secondary btn-sm" data-action="togglePat">Show</button>
          <button type="button" id="btn-verify-pat" class="btn btn-secondary btn-sm" data-action="verifyPatToken">Verify &amp; Auto-Fill</button>
        </div>
        <div id="pat-verify-status" class="hint-text pat-hint"></div>
      </div>

      <div class="form-group" id="form-group-ssh" style="display: none;">
        <label class="form-label" for="form-ssh-key">SSH Key Path <span class="opt">(optional)</span></label>
        <div class="pat-row">
          <input type="text" id="form-ssh-key" class="input-text" placeholder="e.g. ~/.ssh/id_ed25519" autocomplete="off" />
          <button type="button" id="btn-verify-ssh" class="btn btn-secondary btn-sm" data-action="verifySshKey">Test &amp; Auto-Fill</button>
        </div>
        <div id="ssh-verify-status" class="hint-text">Leave blank to use default SSH agent/keys.</div>
      </div>

      <div class="form-group">
        <label class="form-label">Identity Scope</label>
        <div class="radio-deck">
          <label class="radio-item">
            <input type="radio" name="form-scope" value="local" checked />
            <span>Current Repo (local)</span>
          </label>
          <label class="radio-item">
            <input type="radio" name="form-scope" value="global" />
            <span>Global</span>
          </label>
        </div>
      </div>

      <div class="form-actions-row">
        <button type="button" class="btn" id="form-submit-btn" data-action="saveProfileForm">Save Profile</button>
        <button type="button" class="btn btn-secondary" data-action="cancelProfileForm">Cancel</button>
      </div>
    </div>
  </div>

